SELECT COUNT(*) AS brand_new_count
FROM nlq.listings
WHERE condition ILIKE '%brand new%';

SELECT COUNT(*) AS switch_count
FROM nlq.listings
WHERE title ILIKE '%nintendo switch%' OR description ILIKE '%nintendo switch%';

SELECT COUNT(*) AS total_listings
FROM nlq.listings
WHERE meetup_spot ILIKE 'International Village';

SELECT COUNT(*) AS board_game_count
FROM nlq.listings
WHERE title ILIKE '%board game%' OR description ILIKE '%board game%';

SELECT ROUND(100.0 * SUM(CASE WHEN rent_price_per_week IS NOT NULL THEN 1 ELSE 0 END)::numeric / COUNT(*)::numeric, 2) AS rentable_percentage
FROM nlq.listings
WHERE category = 'electronics';

SELECT ROUND(percentile_cont(0.5) WITHIN GROUP (ORDER BY rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS listings_since_oct1
FROM nlq.listings
WHERE (listed_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-10-01';

SELECT COUNT(*) AS five_star_received
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT MIN(rating) AS worst_rating
FROM nlq.my_reviews
WHERE direction = 'received';

SELECT COUNT(*) AS cancelled_rental_requests
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'cancelled';

SELECT ROUND(COALESCE(SUM(agreed_price),0)::numeric,2) AS total_rental_revenue
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT COUNT(*) AS declined_purchase_requests
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'declined';

SELECT COUNT(DISTINCT buyer_id) AS num_students
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'completed';

SELECT COUNT(DISTINCT item_id) AS rented_items_count
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT ROUND(AVG((rental_returned_at AT TIME ZONE 'America/New_York')::date - rental_due_date)::numeric, 2) AS avg_days_late
FROM nlq.deals
WHERE deal_type = 'rental' AND returned_late = true;

SELECT COUNT(*) AS reserved_listings
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS resolved_reports_count
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS four_photo_listings
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(DISTINCT la.item_id) AS only_rent_never_sale
FROM nlq.listings_all la
WHERE la.is_for_rent = true
  AND la.item_id NOT IN (
    SELECT DISTINCT item_id FROM nlq.listings_all WHERE is_for_sale = true
  );

select count(*) as rented_out_count
from nlq.listings_all
where status = 'rented_out';

SELECT ROUND(AVG(buyer_message_count)::numeric, 2) AS avg_buyer_messages,
       ROUND(AVG(seller_message_count)::numeric, 2) AS avg_seller_messages
FROM nlq.conversations;

SELECT COUNT(*) AS conversations_where_buyer_sent_more_messages
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT round(100.0 * SUM(CASE WHEN resolved_at <= filed_at + interval '48 hour' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percent_resolved_within_48h
FROM nlq.reports
WHERE status = 'resolved';

select count(*) as listings_count
from (
  select la.item_id
  from nlq.listings_all la
  join nlq.saved_items si on si.item_id = la.item_id
  where la.status <> 'sold'
  group by la.item_id
  having count(distinct si.student_id) >= 5
) sub;

SELECT
  ROUND(100.0 * chat_cnt / total_cnt, 2) AS percent_with_chat,
  ROUND(100.0 * request_cnt / total_cnt, 2) AS percent_with_request,
  ROUND(100.0 * completed_cnt / total_cnt, 2) AS percent_completed_deal
FROM (
  SELECT COUNT(*)::numeric AS total_cnt FROM nlq.listings_all
) total,
(
  SELECT COUNT(DISTINCT item_id)::numeric AS chat_cnt FROM nlq.conversations
) chats,
(
  SELECT COUNT(DISTINCT item_id)::numeric AS request_cnt FROM nlq.deals WHERE status = 'requested'
) requests,
(
  SELECT COUNT(DISTINCT item_id)::numeric AS completed_cnt FROM nlq.deals WHERE status = 'completed'
) completed;
